package org.jlinalg.cli;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import static org.jlinalg.cli.NextflowFiles.*;

/** Source-compatible Java kinship and separately installed original GEMMA fitting. */
final class GemmaToolsCli {
    private GemmaToolsCli(){ }
    static int run(String[] args,PrintStream output,PrintStream error){
        Path created=null;
        try{
            if(args.length==0||Arrays.equals(args,new String[]{"--help"})){emit(output,help());return output.checkError()?2:0;}
            if(Arrays.equals(args,new String[]{"--profiles"})){emit(output,NextflowJson.json(Map.of("source_lock",SimpleJson.parse(utf8(GemmaRuntime.resource("source-lock.json"))),"native_modes",List.of("gk1","gk2"),"original_modes",List.of("gk1","gk2","lmm1","lmm2","lmm3","lmm4"),"whole_paper_reproduced",false,"P176_literal_0_983_resolved",false,"optimizer_convergence_certified",false)));return output.checkError()?2:0;}
            if(args.length==2&&args[0].equals("--export-runtime-setup")){export(Path.of(args[1]));emit(output,"Separate GEMMA setup exported; no installation or user analysis was run. Read README.txt before permitted setup.");return output.checkError()?2:0;}
            if(args.length==2&&args[0].equals("--verify")){GemmaBundle.verify(Path.of(args[1]),false,()->{});emit(output,"PASS complete GEMMA captured-byte, sample/QC/output and exact-producer checks; no model was refit.\n"+GemmaWorkflow.ACTION);return output.checkError()?2:0;}
            var options=new HashMap<String,String>();var allowed=Set.of("--request","--home","--setup-report","--out","--inspect-runtime");
            for(int i=0;i<args.length;i+=2)if(i+1>=args.length||!allowed.contains(args[i])||options.putIfAbsent(args[i],args[i+1])!=null)throw new IOException("Require complete unique GEMMA options; see --help");
            if(options.containsKey("--inspect-runtime")){if(!options.keySet().equals(Set.of("--inspect-runtime","--setup-report")))throw new IOException("Use --inspect-runtime HOME --setup-report COMPLETED_SETUP_REPORT");var runtime=new GemmaRuntime(Path.of(options.get("--inspect-runtime")),Path.of(options.get("--setup-report")));emit(output,NextflowJson.json(runtime.provenance())+"\nExact runtime integrity checked; no user analysis admitted.");return output.checkError()?2:0;}
            if(!options.keySet().containsAll(Set.of("--request","--out"))||options.containsKey("--home")!=options.containsKey("--setup-report"))throw new IOException("Require --request TYPED.json --out NEW_DIRECTORY; original execution also requires both --home and --setup-report");
            created=GemmaWorkflow.start(Path.of(options.get("--request")),options.containsKey("--home")?Path.of(options.get("--home")):null,options.containsKey("--setup-report")?Path.of(options.get("--setup-report")):null,Path.of(options.get("--out")));emit(output,"Complete GEMMA captured contract: "+created+"\n"+GemmaWorkflow.ACTION);emit(error,"WARNINGS AND REQUIRED ACTION: read "+created.resolve("WARNINGS.md")+", every QC disposition and original diagnostic before downstream use. Optimizer convergence and whole-paper reproduction are not certified.");if(output.checkError()||error.checkError()){GemmaWorkflow.failure(created,"REPORT_RESULT_TO_CALLER",new IOException("Result-report output stream failed"));return 2;}return 0;
        }catch(Exception|LinkageError e){int code=e instanceof GemmaRuntime.Unavailable?3:2;emit(error,(code==3?"SKIP3 DEPENDENT ANALYSIS SKIPPED: ":"FAIL2 NO COMPLETE RESULT: ")+e+"\n"+GemmaWorkflow.ACTION);return error.checkError()?2:code;}
    }
    private static void export(Path supplied)throws IOException{
        Path root=supplied.toAbsolutePath().normalize();if(root.getParent()==null||!root.getParent().toRealPath().equals(root.getParent()))throw new IOException("Require canonical existing setup-export parent");Files.createDirectory(root);
        try{
            var files=new TreeMap<String,Object>();for(String name:GemmaRuntime.RESOURCES){byte[] raw=GemmaRuntime.resource(name);Files.write(root.resolve(name),raw,StandardOpenOption.CREATE_NEW);files.put(name,GemmaRuntime.bytesPin(raw));}
            String readme="GEMMA PRIVATE ORIGINAL RUNTIME SETUP ONLY\n\nNo runtime was installed or user analysis run by this export. Require permitted Linux x86_64 Python>=3.11, setsid, prlimit and readable /proc; use Linux Python/Java inside WSL on Windows. Source executables are original unmodified GPL3 GEMMA0.98.1/0.98.3/0.98.5, not PanGEMMA. Exact official source/archive URLs and complete hashes are in source-lock.json; retain original sources and licenses privately.\n\nFrom this export, with absolute paths and NEW home/report:\npython3 -B setup.py --home /absolute/NEW_HOME --report /absolute/NEW_REPORT --cache /absolute/EXISTING_CACHE --allow-install --allow-download\n\nFor offline setup, cache exact gemma-0.98.1.gz, gemma-0.98.3.gz and gemma-0.98.5.gz using the locked official release assets and omit --allow-download. To recheck an existing completed home, supply a NEW report, matching export and existing cache with no install/download flags. Recheck never refreshes a changed runtime seal. Require COMPLETED.json, WARNINGS.md and all9original synthetic controls across3editions. Health admits no user analysis.\n\nSKIP3: permitted platform/runtime/install/download/access unavailable; dependent analysis skipped. Supply the named exact prerequisite or retain the skip. FAIL2: invalid or changed source/runtime, health/process/numerical/capacity failure. Preserve partial attempts; correct the cause using NEW paths. Never overwrite or reseal changed original files. Analysis never invokes setup or downloads software.\n\nRead docs/literature/GEMMA_WORKFLOWS.md for typed requests, narrow scope and required actions.\n";Files.writeString(root.resolve("README.txt"),readme,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);files.put("README.txt",pin(root.resolve("README.txt"),65536,()->{}));writeJson(root.resolve("export.json"),Map.of("schema_version",1,"status","EXPORTED_GEMMA_SETUP_NOT_RUN","user_analysis_admitted",false,"files",files));
        }catch(IOException|RuntimeException e){try{Files.writeString(root.resolve("FAILURE.txt"),"Setup export failed; no runtime installed or user analysis admitted. Preserve this attempt, correct the cause and export to a NEW path.\n"+e+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);}catch(IOException diagnostic){e.addSuppressed(diagnostic);}throw e;}
    }
    private static String help(){return "gemma-tools --profiles\n--export-runtime-setup NEW_DIRECTORY\n--inspect-runtime PRIVATE_HOME --setup-report COMPLETED_SETUP_REPORT\n--request TYPED_REQUEST.json --out NEW_DIRECTORY [--home PRIVATE_HOME --setup-report COMPLETED_SETUP_REPORT]\n--verify COMPLETE_CAPTURED_RESULT\n\nNative Java gk1/gk2 kinship works on Windows and Linux. Original unmodified Linux x86_64 GEMMA0.98.1/0.98.3/0.98.5 performs gk1/gk2 or univariate LMM1Wald/2LRT/3score/4all-tests. Require an explicit phenotype, FID/IID order sidecar, genome-build declaration, QC and capacities. Association also requires an explicit ordered kinship and source-default optimizer profile; author-unreported choices are not inferred. Exact producing JAR required for portable verification. No analysis-time installation, fallback model, PanGEMMA substitution or whole-paper claim.\n\nRead docs/literature/GEMMA_WORKFLOWS.md for copyable requests and warnings.\n\n"+GemmaWorkflow.ACTION;}
    private static void emit(PrintStream stream,String text){stream.writeBytes((text+"\n").getBytes(StandardCharsets.UTF_8));}
}
